\caption{Adaptive algorithm to solve Problem $(\mathcal{P}^*)$.}\small
\label{alg:adaptive}
\begin{algorithmic}
\item Repeat, for $t=1,\cdots,T-1$:
\begin{itemize}
    \item[] \textbf{1. Optimize.} Define $\beta_t=\alpha_T\left(1-r^{t-1}\right)$ and $\gamma_t$ such that $\sum_{s=1}^{t-1} A^{\textsc{ad}}_s=\gamma_t m^{\beta_t}+o\left(m^{\beta_t}\right)$. Solve Problem $\left(\mathcal{Q}^*_{T-t+1}\left(m-\sum_{s=1}^{t-1}B^{\textsc{ad}}_s,\sum_{s=1}^{t-1} A^{\textsc{ad}}_s\right)\right)$. Retrieve solution $A^\dagger_1,\cdots,A^\dagger_{T-t+1}$.
    \item[] \textbf{2. Commit immediate decision.} Implement the first-period decision: $A^{\textsc{ad}}_t=A^\dagger_1$.
    \item[] \textbf{3. Observe realizations.} Sample $B^{\textsc{ad}}_t\sim \mathrm{Bino}\left(A^{\textsc{ad}}_t, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{t-1} A^{\textsc{ad}}_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$.
\end{itemize}
\item $A^{\textsc{ad}}_T\gets\left(\mathcal{S}^*\left(m-\sum_{s=1}^{T-1}B^{\textsc{ad}}_s,\sum_{s=1}^{T-1} A^{\textsc{ad}}_s\right)\right)$. Sample $B^{\textsc{ad}}_T\sim \mathrm{Bino}\left(A^{\textsc{ad}}_T, 1- \frac{\varepsilon\cdot p}{\left(\sum_{s=1}^{T-1} A^{\textsc{ad}}_s +1\right)^r}-\varepsilon\cdot(1-p)\right)$.
\end{algorithmic}

